func (this *Backpack) HandleOHLCV(client any, message any) {
	//
	//     {
	//         data: {
	//             E: '1754519557526056',
	//             T: '2025-08-07T00:00:00',
	//             X: false,
	//             c: '3680.520000000',
	//             e: 'kline',
	//             h: '3681.370000000',
	//             l: '3667.650000000',
	//             n: 255,
	//             o: '3670.150000000',
	//             s: 'ETH_USDC',
	//             t: '2025-08-06T22:00:00',
	//             v: '62.2621000'
	//         },
	//         stream: 'kline.2h.ETH_USDC'
	//     }
	//
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "data", map[string]any{}))
	var marketId *string = this.SafeString(data, "s")
	var market map[string]any = ccxt.MapTyped(this.Market(marketId))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var stream *string = this.SafeString(message, "stream", "")
	var parts []string = ccxt.Split(stream, ".")
	var timeframe *string = this.SafeString(parts, 1, "")
	if !(ccxt.InOp(this.Ohlcvs, symbol)) {
		ccxt.AddElementToObject(this.Ohlcvs, symbol, map[string]any{})
	}
	if !(ccxt.InOp(ccxt.GetValue(this.Ohlcvs, symbol), timeframe)) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored := ccxt.NewArrayCacheByTimestamp(limit)
		ccxt.AddElementToObject(ccxt.GetValue(this.Ohlcvs, symbol), timeframe, stored)
	}
	var ohlcv any = ccxt.GetValue(ccxt.GetValue(this.Ohlcvs, symbol), timeframe)
	var parsed any = this.ParseWsOHLCV(data)
	ohlcv.(ccxt.Appender).Append(parsed)
	var messageHash string = "candles:" + *symbol + ":" + *timeframe
	client.(ccxt.ClientInterface).Resolve([]any{symbol, timeframe, ohlcv}, messageHash)
}
func (this *Backpack) ParseWsOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//     {
	//         E: '1754519557526056',
	//         T: '2025-08-07T00:00:00',
	//         X: false,
	//         c: '3680.520000000',
	//         e: 'kline',
	//         h: '3681.370000000',
	//         l: '3667.650000000',
	//         n: 255,
	//         o: '3670.150000000',
	//         s: 'ETH_USDC',
	//         t: '2025-08-06T22:00:00',
	//         v: '62.2621000'
	//     },
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return []any{this.Parse8601(this.SafeString(ohlcv, "T")), this.SafeNumber(ohlcv, "o"), this.SafeNumber(ohlcv, "h"), this.SafeNumber(ohlcv, "l"), this.SafeNumber(ohlcv, "c"), this.SafeNumber(ohlcv, "v")}
}

