func (this *Backpack) HandleTrades(client any, message any) {
	//
	//     {
	//         data: {
	//             E: '1754601477746429',
	//             T: '1754601477744000',
	//             a: '5121860761',
	//             b: '5121861755',
	//             e: 'trade',
	//             m: false,
	//             p: '3870.25',
	//             q: '0.0008',
	//             s: 'ETH_USDC_PERP',
	//             t: 10782547
	//         },
	//         stream: 'trade.ETH_USDC_PERP'
	//     }
	//
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "data", map[string]any{}))
	var marketId *string = this.SafeString(data, "s")
	var market map[string]any = ccxt.MapTyped(this.Market(marketId))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	if !(ccxt.InOp(this.Trades, symbol)) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		var stored *ccxt.ArrayCache = ccxt.NewArrayCache(limit)
		ccxt.AddElementToObject(this.Trades, symbol, stored)
	}
	var cache any = ccxt.GetValue(this.Trades, symbol)
	var trade map[string]any = ccxt.MapTyped(this.ParseWsTrade(data, market))
	cache.(ccxt.Appender).Append(trade)
	var messageHash string = "trades:" + *symbol
	client.(ccxt.ClientInterface).Resolve(cache, messageHash)
	client.(ccxt.ClientInterface).Resolve(cache, "trades")
}
func (this *Backpack) ParseWsTrade(trade any, optionalArgs ...any) any {
	//
	//     {
	//         E: '1754601477746429',
	//         T: '1754601477744000',
	//         a: '5121860761',
	//         b: '5121861755',
	//         e: 'trade',
	//         m: false,
	//         p: '3870.25',
	//         q: '0.0008',
	//         s: 'ETH_USDC_PERP',
	//         t: 10782547
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var microseconds *int64 = this.SafeInteger(trade, "E", 0)
	var timestamp int64 = this.ParseToInt(ccxt.Divide(microseconds, 1000))
	var id *string = this.SafeString(trade, "t")
	var marketId *string = this.SafeString(trade, "s")
	market = ccxt.MapTyped(this.SafeMarket(marketId, market))
	var isBuyerMaker *bool = this.SafeBool(trade, "m")
	var side any = nil
	var takerOrMaker any = nil
	if isBuyerMaker != nil {
		takerOrMaker = "taker"
		if isBuyerMaker != nil && *isBuyerMaker {
			side = "sell"
		} else {
			side = "buy"
		}
	}
	var price *string = this.SafeString(trade, "p")
	var amount *string = this.SafeString(trade, "q")
	var orderId *string = nil
	if ccxt.IsEqual(side, "buy") {
		orderId = this.SafeString(trade, "b")
	} else {
		orderId = this.SafeString(trade, "a")
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       ccxt.GetValue(market, "symbol"),
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        price,
		"amount":       amount,
		"cost":         nil,
		"fee": map[string]any{
			"currency": nil,
			"cost":     nil,
		},
	}, market)
}

