func (this *Backpack) HandleOrder(client any, message any) {
	//
	//     {
	//         data: {
	//             E: '1754939110175843',
	//             O: 'USER',
	//             Q: '4.30',
	//             S: 'Bid',
	//             T: '1754939110174703',
	//             V: 'RejectTaker',
	//             X: 'New',
	//             Z: '0',
	//             e: 'orderAccepted',
	//             f: 'GTC',
	//             i: '5406825793',
	//             o: 'MARKET',
	//             q: '0.0010',
	//             r: false,
	//             s: 'ETH_USDC',
	//             t: null,
	//             z: '0'
	//         },
	//         stream: 'account.orderUpdate.ETH_USDC'
	//     }
	//
	var messageHash string = "orders"
	var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "data", map[string]any{}))
	var marketId *string = this.SafeString(data, "s")
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId))
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var parsed map[string]any = ccxt.MapTyped(this.ParseWsOrder(data, market))
	var orders any = this.Orders
	if ccxt.IsEqual(orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		orders = ccxt.NewArrayCacheBySymbolById(limit)
		this.Orders = orders
	}
	orders.(ccxt.Appender).Append(parsed)
	client.(ccxt.ClientInterface).Resolve(orders, messageHash)
	var symbolSpecificMessageHash string = messageHash + ":" + *symbol
	client.(ccxt.ClientInterface).Resolve(orders, symbolSpecificMessageHash)
}
func (this *Backpack) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         E: '1754939110175879',
	//         L: '4299.16',
	//         N: 'ETH',
	//         O: 'USER',
	//         Q: '4.30',
	//         S: 'Bid',
	//         T: '1754939110174705',
	//         V: 'RejectTaker',
	//         X: 'Filled',
	//         Z: '4.299160',
	//         e: 'orderFill',
	//         f: 'GTC',
	//         i: '5406825793',
	//         l: '0.0010',
	//         m: false,
	//         n: '0.000001',
	//         o: 'MARKET',
	//         q: '0.0010',
	//         r: false,
	//         s: 'ETH_USDC',
	//         t: 2888471,
	//         z: '0.0010'
	//     },
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "i")
	var clientOrderId *string = this.SafeString(order, "c")
	var microseconds *int64 = this.SafeInteger(order, "E", 0)
	var timestamp int64 = this.ParseToInt(ccxt.Divide(microseconds, 1000))
	var status *string = this.ParseWsOrderStatus(this.SafeString(order, "X"), market)
	var marketId *string = this.SafeString(order, "s")
	market = ccxt.MapTyped(this.SafeMarket(marketId, market))
	var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(market, "symbol"))
	var typeVar *string = this.SafeStringLower(order, "o")
	var timeInForce *string = this.SafeString(order, "f")
	var side *string = this.ParseWsOrderSide(this.SafeString(order, "S"))
	var price *string = this.SafeString(order, "p")
	var triggerPrice *float64 = this.SafeNumber(order, "P")
	var amount *string = this.SafeString(order, "q")
	var cost *string = this.SafeString(order, "Z")
	var filled *string = this.SafeString(order, "l")
	var fee map[string]any = nil
	var feeCurrency *string = this.SafeString(order, "N")
	if feeCurrency != nil {
		fee = map[string]any{
			"currency": feeCurrency,
			"cost":     nil,
		}
	}
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"side":               side,
		"price":              price,
		"stopPrice":          nil,
		"triggerPrice":       triggerPrice,
		"average":            nil,
		"amount":             amount,
		"cost":               cost,
		"filled":             filled,
		"remaining":          nil,
		"fee":                fee,
		"trades":             nil,
		"info":               order,
	}, market)
}
func (this *Backpack) ParseWsOrderStatus(status *string, optionalArgs ...any) *string {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var statuses map[string]any = map[string]any{
		"New":             "open",
		"Filled":          "closed",
		"Cancelled":       "canceled",
		"Expired":         "canceled",
		"PartiallyFilled": "open",
		"TriggerPending":  "open",
		"TriggerFailed":   "rejected",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Backpack) ParseWsOrderSide(side *string) *string {
	var sides map[string]any = map[string]any{
		"Bid": "buy",
		"Ask": "sell",
	}
	return this.SafeString(sides, side, side)
}

/**
 * @method
 * @name backpack#watchPositions
 * @description watch all open positions
 * @see https://docs.backpack.exchange/#tag/Streams/Private/ccxt.Position-update
 * @param {string[]} [symbols] list of unified market symbols to watch positions for
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Backpack) WatchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Backpack) watchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	symbols = this.MarketSymbols(symbols)
	var messageHashes []any = []any{}
	var topics []any = []any{}
	if symbols != nil {
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			messageHashes = append(messageHashes, "positions"+":"+*symbol)
			topics = append(topics, ccxt.Add("account.positionUpdate.", this.MarketId(symbol)))
		}
	} else {
		messageHashes = append(messageHashes, "positions")
		topics = append(topics, "account.positionUpdate")
	}

	positions := (<-this.WatchPrivateAsync(topics, messageHashes, params))
	ccxt.PanicOnError(positions)
	if this.NewUpdates {

		ch <- positions
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(this.Positions, symbols, since, limit, true)
	return nil
}

